CustomField.formula:
IF(DueFilterDays__c = -30 , '30 days Prior',
	IF(DueFilterDays__c = -15, '15 Days Prior',
		IF(DueFilterDays__c = -7, '7 Days Prior',
                            IF(DueFilterDays__c = -1, '1 Day Prior',
			IF(DueFilterDays__c < -30,'More than 30 days Prior',
				IF(DueFilterDays__c >= 0,'More than 1 days Over Due',
					IF(DueFilterDays__c < 0 && DueFilterDays__c > -7,'More than 1 day to 6 days Prior',
						IF(DueFilterDays__c < -15 && DueFilterDays__c > -7,'More than 8 day to 14 days Prior','')
					)
				)
			)
                   )
		)
	)
)
